"""Compile root-level rule sources into Sing-box and Mihomo formats."""

import argparse
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
import json
import os
from pathlib import Path
import subprocess
import sys

import yaml


WORKFLOW_DIR = Path(__file__).resolve().parents[1]
if str(WORKFLOW_DIR) not in sys.path:
    sys.path.insert(0, str(WORKFLOW_DIR))

from rule_set import (
    build_singbox_json,
    read_json_document,
    read_text_rules,
    rules_from_document,
    supported_rule_set_version,
)


GENERATED_YAML_HEADER = (
    "# Generated by convert_rule_formats.py; edit the source rule file instead.\n"
)
SOURCE_PRIORITY = {".yaml": 0, ".yml": 1, ".txt": 2, ".json": 3, ".list": 4}


@dataclass(frozen=True)
class ProcessResult:
    path: Path
    success: bool
    messages: tuple[str, ...]


def write_if_changed(path, content):
    encoded = content.encode("utf-8")
    if path.exists() and path.read_bytes() == encoded:
        return False
    temporary_path = path.with_name(f".{path.name}.tmp")
    try:
        temporary_path.write_bytes(encoded)
        temporary_path.replace(path)
    except OSError:
        temporary_path.unlink(missing_ok=True)
        raise
    return True


def compile_command(command, label):
    try:
        result = subprocess.run(command, capture_output=True, text=True, check=False)
    except OSError as error:
        return False, f"{label}: {error}"
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip() or "unknown error"
        return False, f"{label}: {detail}"
    return True, ""


def compile_singbox(json_path):
    output_path = json_path.with_suffix(".srs")
    temporary_path = output_path.with_suffix(".srs.tmp")
    temporary_path.unlink(missing_ok=True)
    success, error = compile_command(
        [
            "sing-box",
            "rule-set",
            "compile",
            "--output",
            str(temporary_path),
            str(json_path),
        ],
        f"Sing-box compile {json_path}",
    )
    if not success:
        temporary_path.unlink(missing_ok=True)
        return False, error
    temporary_path.replace(output_path)
    return True, f"{json_path} -> {output_path}"


def generated_yaml(lines):
    return "payload:\n" + "".join(
        f"    - {json.dumps(line, ensure_ascii=False)}\n" for line in lines
    ) + GENERATED_YAML_HEADER


def write_rule_texts(list_path, lines):
    changes = []
    if write_if_changed(list_path, "\n".join(lines) + "\n"):
        changes.append(list_path)

    yaml_path = list_path.with_suffix(".yaml")
    if yaml_path.exists() and GENERATED_YAML_HEADER not in yaml_path.read_text(
        encoding="utf-8-sig"
    ):
        return changes
    if write_if_changed(yaml_path, generated_yaml(lines)):
        changes.append(yaml_path)
    return changes


def mihomo_rules(rules):
    domain_rules = {
        field: values
        for field, values in rules.items()
        if field in {"domain", "domain_suffix"}
    }
    if domain_rules:
        return domain_rules
    if rules.get("ip_cidr"):
        return {"ip_cidr": rules["ip_cidr"]}
    raise ValueError("no exact domains, domain suffixes or IP CIDRs to export as MRS")


def build_mihomo_list(rules):
    fields = set(rules)
    behavior = "domain" if fields <= {"domain", "domain_suffix"} else "ipcidr"
    lines = []
    for field, values in sorted(rules.items()):
        for value in sorted(values):
            lines.append(f"+.{value}" if field == "domain_suffix" else value)
    return behavior, lines


def compile_mihomo(source_path, output_dir, rules):
    selected = mihomo_rules(rules)
    omitted = sorted(set(rules) - set(selected))
    behavior, lines = build_mihomo_list(selected)
    list_path = output_dir / source_path.with_suffix(".list").name
    list_path.parent.mkdir(parents=True, exist_ok=True)
    changed_paths = write_rule_texts(list_path, lines)

    output_path = list_path.with_suffix(".mrs")
    temporary_path = output_path.with_suffix(".mrs.tmp")
    temporary_path.unlink(missing_ok=True)
    success, error = compile_command(
        [
            "mihomo",
            "convert-ruleset",
            behavior,
            "text",
            str(list_path),
            str(temporary_path),
        ],
        f"Mihomo compile {source_path}",
    )
    if not success:
        temporary_path.unlink(missing_ok=True)
        return False, error, ()
    temporary_path.replace(output_path)

    details = f"{list_path}, {output_path} ({behavior}, {len(lines)} rules)"
    if omitted:
        details += f"; JSON/SRS retain {', '.join(omitted)}"
    return True, details, tuple(changed_paths)


def remove_legacy_subsets(source_path, output_dir):
    removed = []
    for directory in {source_path.parent.resolve(), output_dir.resolve()}:
        for tag in ("-domain", "-ipcidr"):
            for suffix in (".json", ".srs", ".list", ".yaml", ".mrs"):
                candidate = directory / f"{source_path.stem}{tag}{suffix}"
                if candidate.is_file() and candidate.resolve().parent == directory:
                    candidate.unlink()
                    removed.append(candidate)
    return removed


def source_files(root):
    sources = {}
    for path in sorted(root.iterdir()):
        suffix = path.suffix.lower()
        if not path.is_file() or suffix not in SOURCE_PRIORITY or path.name == "links.txt":
            continue
        if suffix == ".yaml" and GENERATED_YAML_HEADER in path.read_text(
            encoding="utf-8-sig"
        ):
            continue
        previous = sources.get(path.stem)
        if previous is None or SOURCE_PRIORITY[suffix] < SOURCE_PRIORITY[
            previous.suffix.lower()
        ]:
            sources[path.stem] = path

    for stem, path in sorted(sources.items()):
        if any(
            stem.endswith(tag) and stem[: -len(tag)] in sources
            for tag in ("-domain", "-ipcidr")
        ):
            continue
        yield path


def process_file(path, output_dir, rule_set_version):
    messages = []
    try:
        if path.suffix.lower() == ".json":
            document = read_json_document(path)
            rules = rules_from_document(document)
            if document.get("version") != rule_set_version:
                document["version"] = rule_set_version
                write_if_changed(
                    path,
                    json.dumps(document, ensure_ascii=False, indent=2) + "\n",
                )
                messages.append(f"updated JSON rule-set version to {rule_set_version}")
            if not rules:
                messages.append("skipped Mihomo export: no supported Sing-box rule fields")
                return ProcessResult(path, True, tuple(messages))
            success, detail = compile_singbox(path)
            if not success:
                return ProcessResult(path, False, (detail,))
            messages.append(detail)
        else:
            rules = read_text_rules(path)
            if not rules:
                return ProcessResult(
                    path,
                    True,
                    ("skipped: no supported rules",),
                )
            json_path = path.with_suffix(".json")
            changed = write_if_changed(
                json_path,
                json.dumps(
                    build_singbox_json(rules, rule_set_version),
                    ensure_ascii=False,
                    indent=2,
                )
                + "\n",
            )
            messages.append(f"{'updated' if changed else 'kept'} {json_path}")
            success, detail = compile_singbox(json_path)
            if not success:
                return ProcessResult(path, False, (detail,))
            messages.append(detail)

        success, detail, changed_paths = compile_mihomo(path, output_dir, rules)
        if not success:
            return ProcessResult(path, False, (detail,))
        messages.append(detail)
        if changed_paths:
            messages.append(
                "updated " + ", ".join(str(changed_path) for changed_path in changed_paths)
            )
        removed = remove_legacy_subsets(path, output_dir)
        if removed:
            messages.append("removed " + ", ".join(str(candidate) for candidate in removed))
        return ProcessResult(path, True, tuple(messages))
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as error:
        return ProcessResult(path, False, (str(error),))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=WORKFLOW_DIR.parent)
    parser.add_argument("--output-dir", type=Path)
    parser.add_argument("--jobs", type=int, default=min(4, os.cpu_count() or 1))
    args = parser.parse_args()
    if args.jobs < 1:
        parser.error("--jobs must be at least 1")

    root = args.root.resolve()
    output_dir = (args.output_dir or root).resolve()
    files = list(source_files(root))
    if not files:
        print("No supported .txt, .list, .yaml, .yml, or .json inputs found.")
        return 0

    rule_set_version = supported_rule_set_version()
    workers = min(args.jobs, len(files))
    with ThreadPoolExecutor(max_workers=workers) as executor:
        futures = [
            executor.submit(process_file, path, output_dir, rule_set_version)
            for path in files
        ]
        results = [future.result() for future in futures]

    for result in results:
        label = "[OK]" if result.success else "[ERROR]"
        print(f"{label} {result.path}")
        for message in result.messages:
            print(f"  {message}")

    failed = sum(not result.success for result in results)
    summary = (
        f"Full rebuild: {len(files)} rule sources, {len(files) - failed} succeeded, "
        f"{failed} failed (rule-set version {rule_set_version}, {workers} workers)."
    )
    print(summary)
    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a", encoding="utf-8") as report:
            report.write(summary + "\n")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
